// Shared definition of the 1 documented Interactive Learning Audio sample project, used by
// both the regeneration script (scripts/generate-audio-player-samples.mjs) and the drift
// test (tests/unit/audio-player-samples.test.js) so the two can never silently disagree —
// same reasoning tests/fixtures/interactive-video-sample-definitions.mjs already
// established for Interactive Video's own samples.

import { COMPONENT_REGISTRY, getComponentById, getDefaultConfig } from '../../js/component-registry.js';
import { buildProject } from '../../js/storage.js';
import { BUILT_IN_THEMES, DEFAULT_THEME_ID } from '../../js/themes.js';

const theme = BUILT_IN_THEMES.find(item => item.id === DEFAULT_THEME_ID);
const entry = getComponentById(COMPONENT_REGISTRY, 'audio-player');
if (!entry) throw new Error('audio-player is not registered.');

// The same clip components/audio-player.js's own defaultConfig already uses — a freely
// usable royalty-free demo track, nothing to license. Not a stand-in for a real episode:
// an author importing this sample is expected to replace it with their own audio.
export const SAMPLE_AUDIO_URL = 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3';

const baseFields = {
  blockTitle: 'SAMPLE', blockHeadline: 'Interactive Learning Audio sample', blockDesc: 'Generated by scripts/generate-audio-player-samples.mjs — see docs/AUDIO-PLAYER.md "Sample configuration".',
  colorPrimary: '#00388F', colorAccent: '#009FDB', colorBg: '#FFFFFF', colorText: '#000000',
  borderRadius: '12', shadowDepth: 'soft', borderOutline: true,
  accordionMulti: true, accordionAnimation: true, iconStyle: 'chevron',
  trackCompletion: true, completionMsg: 'Activity complete!'
};

export const AUDIO_PLAYER_SAMPLES = [
  {
    filename: 'podcast-episode.json',
    name: 'Interactive Learning Audio Sample — Podcast Episode',
    overrides: {
      presentationMode: 'podcast',
      progressPersistence: true,
      chapters: [
        '0:00 | Welcome | What this episode covers and who it is for',
        '0:45 | The core idea | The single concept the rest of the episode builds on',
        '2:10 | A worked example | Walking through one realistic scenario step by step',
        '3:40 | Common mistakes | Three mistakes learners make and how to avoid them',
        '5:00 | Wrap-up | A short recap and where to go next'
      ].join('\n'),
      transcriptSegments: [
        '0:00 | Host | Welcome back to the show — today we are covering a concept that trips up almost everyone the first time they meet it.',
        '0:45 | Host | Here is the core idea, as simply as I can put it: small, consistent steps beat one large effort every time.',
        '2:10 | Host | Let’s walk through a realistic example so this is not just theory.',
        '3:40 | Host | Now, the three mistakes I see most often — and how to sidestep each one.',
        '5:00 | Host | That is the episode. Quick recap, and a pointer to where you can practice this yourself.'
      ].join('\n'),
      takeaways: [
        'Small, consistent steps beat one large effort.',
        'Walk through a realistic example before trusting a new idea in production.',
        'Watch for the three common mistakes covered in this episode.'
      ].join('\n'),
      takeawaysVisibility: 'afterCompletion',
      items: [{
        title: 'Episode 12: Building the Habit',
        seriesLabel: 'The Practical Skills Podcast',
        description: 'A short, focused episode on turning a new skill into a lasting habit — with a worked example and the three mistakes to avoid.',
        content: SAMPLE_AUDIO_URL,
        transcript: ''
      }]
    }
  }
];

// Deterministic id/dates: a fresh build must byte-for-byte match the committed file (the
// drift test's whole point), so nothing here may vary run-to-run the way
// buildProject()'s own `id`/`createdAt` defaults (createProjectId(), Date.now()) would.
const FIXED_CREATED_AT = '2026-01-01T00:00:00.000Z';

export function buildSampleProject(sample) {
  const config = { ...baseFields, ...getDefaultConfig(entry), ...sample.overrides };
  return buildProject({
    id: `audio-player-sample-${sample.filename.replace('.json', '')}`,
    name: sample.name,
    componentId: 'audio-player',
    createdAt: FIXED_CREATED_AT,
    config,
    activeTheme: theme,
    componentOverrides: {},
    uiTheme: 'light',
    settings: undefined
  });
}
